// Win32: what the GUI uses beyond windows.c, declared as it declares it.
// Only what Windows XP has is imported; newer functions are looked up
// (load_guiapi), as are those of DLLs that are not KnownDLLs (uxtheme,
// shlwapi), by their full path, lest one beside the program be loaded.

typedef struct { i32 x, y; } point;
typedef struct { i32 left, top, right, bottom; } rect;

typedef iz (__stdcall *wndproc)(iptr, u32, uptr, iz);

typedef struct {
    u32        size;
    u32        style;
    wndproc    proc;
    i32        clsextra, wndextra;
    iptr       instance, icon, cursor, background;
    c16 const *menuname, *classname;
    iptr       iconsm;
} wndclassex;

typedef struct {
    iptr  hwnd;
    u32   message;
    uptr  wparam;
    iz    lparam;
    u32   time;
    point pt;
} winmsg;

typedef struct {
    iptr hdc;
    b32  erase;
    rect paint;
    b32  restore, incupdate;
    u8   reserved[32];
} paintstruct;

typedef struct {
    iptr from;
    uptr id;
    u32  code;
} nmhdr;

typedef struct {
    u32  mask;
    i32  item, subitem;
    u32  state, statemask;
    c16 *text;
    i32  textmax;
    i32  image;
    iz   lparam;
    i32  indent;
} lvitem;  // the fields of XP's, without Vista's groups

typedef struct {
    nmhdr  hdr;
    lvitem item;
} nmlvdispinfo;

typedef struct {
    nmhdr hdr;
    i32   item, subitem;
    u32   newstate, oldstate, changed;
    point action;
    iz    lparam;
    u32   keyflags;  // NMITEMACTIVATE's, not NMLISTVIEW's
} nmlistview;

typedef struct __attribute((packed)) {
    nmhdr hdr;
    u16   vkey;
    u32   flags;
} nmkeydown;  // NMLVKEYDOWN and NMTVKEYDOWN

typedef struct {
    u32  mask;
    i32  fmt;
    i32  cx;
    c16 *text;
    i32  textmax;
    i32  subitem;
    i32  image, order;
} lvcolumn;

typedef struct {
    nmhdr hdr;
    i32   from, to;
    u32   newstate, oldstate;
} nmlvodstatechange;

typedef struct {
    nmhdr hdr;
    u32   stage;
    iptr  hdc;
    rect  rc;
    uptr  itemspec;
    u32   itemstate;
    iz    itemlparam;
} nmcustomdraw;

typedef struct {
    nmcustomdraw nmcd;
    u32          clrtext, clrtextbk;
    i32          subitem;
} nmlvcustomdraw;  // its first fields

typedef struct {
    point pt;
    u32   flags;
    i32   item, subitem, group;
} lvhittestinfo;

typedef struct {
    u32  mask;
    iptr item;
    u32  state, statemask;
    c16 *text;
    i32  textmax;
    i32  image, selimage;
    i32  children;
    iz   lparam;
} tvitem;

typedef struct {
    tvitem base;
    i32    integral;
    u32    stateex;
    iptr   hwnd;
    i32    expandedimage;
    i32    reserved;
} tvitemex;

typedef struct {
    iptr     parent;
    iptr     after;
    tvitemex item;
} tvinsertstruct;

typedef struct {
    nmhdr  hdr;
    u32    action;
    tvitem old;
    tvitem new;
    point  drag;
} nmtreeview;

typedef struct {
    nmhdr  hdr;
    tvitem item;
} nmtvdispinfo;

typedef struct {
    point pt;
    u32   flags;
    iptr  item;
} tvhittestinfo;

typedef struct {
    i32  bitmap;
    i32  command;
    u8   state;
    u8   style;
    u8   reserved[sizeof(void *)-2];
    uptr data;
    iz   string;
} tbbutton;

typedef struct {
    nmhdr    hdr;
    i32      item;
    tbbutton button;
    i32      textlen;
    c16     *text;
    rect     rc;
} nmtoolbar;

typedef struct {
    nmhdr hdr;
    c16  *text;
    c16   sztext[80];
    iptr  instance;
    u32   flags;
    iz    lparam;
} nmttdispinfo;

typedef struct {
    i32 height, width, escapement, orientation, weight;
    u8  italic, underline, strikeout, charset;
    u8  outprecision, clipprecision, quality, pitchandfamily;
    c16 facename[32];
} logfont;

typedef struct {
    u32     size;
    i32     borderwidth, scrollwidth, scrollheight;
    i32     captionwidth, captionheight;
    logfont captionfont;
    i32     smcaptionwidth, smcaptionheight;
    logfont smcaptionfont;
    i32     menuwidth, menuheight;
    logfont menufont, statusfont, messagefont;
    i32     paddedborderwidth;  // Vista's: leave out for XP (size 500)
} nonclientmetrics;

typedef struct {
    i32 height, ascent, descent, internalleading, externalleading;
    i32 avecharwidth, maxcharwidth, weight, overhang;
    i32 digitizedaspectx, digitizedaspecty;
    c16 firstchar, lastchar, defaultchar, breakchar;
    u8  italic, underlined, struckout, pitchandfamily, charset;
} textmetric;

typedef struct {
    u32 size;
    i32 width, height;
    u16 planes, bitcount;
    u32 compression, sizeimage;
    i32 xpelspermeter, ypelspermeter;
    u32 clrused, clrimportant;
} bitmapinfoheader;

typedef struct {
    b32  icon;
    u32  xhotspot, yhotspot;
    iptr mask, color;
} iconinfo;

typedef struct {
    iptr icon;
    i32  iicon;
    u32  attributes;
    c16  displayname[260];
    c16  typename[80];
} shfileinfo;

typedef struct {
    u32        size;
    u32        mask;
    iptr       hwnd;
    c16 const *verb, *file, *params, *dir;
    i32        show;
    iptr       instapp;
    void      *idlist;
    c16 const *class;
    iptr       hkeyclass;
    u32        hotkey;
    iptr       icon;
    iptr       process;
} shellexecuteinfo;

typedef struct {
    u32        size;
    iptr       owner, instance;
    c16 const *filter;
    c16       *customfilter;
    u32        maxcustfilter, filterindex;
    c16       *file;
    u32        maxfile;
    c16       *filetitle;
    u32        maxfiletitle;
    c16 const *initialdir, *title;
    u32        flags;
    u16        fileoffset, fileextension;
    c16 const *defext;
    iz         custdata;
    void      *hook;
    c16 const *templatename;
    void      *reserved;
    u32        reserved2, flagsex;
} openfilename;

typedef struct {
    iptr       owner;
    void      *root;
    c16       *displayname;
    c16 const *title;
    u32        flags;
    void      *callback;
    iz         lparam;
    i32        image;
} browseinfo;

typedef struct {
    u32  cb;
    c16 *reserved, *desktop, *title;
    u32  x, y, xsize, ysize, xcount, ycount, fill, flags;
    u16  show, reserved2;
    u8  *reserved2p;
    iptr input, output, error;
} startupinfo;

typedef struct {
    iptr process, thread;
    u32  pid, tid;
} processinfo;

typedef struct {
    u32  size;
    rect monitor, work;
    u32  flags;
} monitorinfo;

typedef struct {
    u32   length, flags, showcmd;
    point min, max;
    rect  normal;
} windowplacement;

typedef struct {
    u32 mask;
    i32 cxy;
    c16 *text;
    iptr bm;
    i32 textmax;
    i32 fmt;
    iz  lparam;
    i32 image, order;
    u32 type;
    void *filter;
    u32 state;
} hditem;

typedef struct {
    point reserved, maxsize, maxposition, mintracksize, maxtracksize;
} minmaxinfo;

typedef struct {
    u16   format;
    void *ptd;
    u32   aspect;
    i32   index;
    u32   tymed;
} formatetc;

typedef struct {
    u32   tymed;
    iptr  hglobal;
    void *unkforrelease;
} stgmedium;

typedef struct {
    u32   files;
    point pt;
    b32   nc;
    b32   wide;
} dropfiles;

