_Static_assert(sizeof(hditem) == (sizeof(void *)==8 ? 72 : 48), "");
_Static_assert(sizeof(formatetc) == (sizeof(void *)==8 ? 32 : 20), "");
_Static_assert(sizeof(stgmedium) == (sizeof(void *)==8 ? 24 : 12), "");
_Static_assert(sizeof(dropfiles) == 20, "");

